//! Exact bowl sample (src/scene/samples/bowl.gcad) through the real bridge JSON
//! (fixtures/bowl-taper.json, regenerated by fixtures/dump-bowl-taper.mts).
//! Runs the full export, then probes every face of the bowl (outer wall, cavity
//! wall, floor, underside, rim) with rays against the analytic field and
//! reports surface points farther than half a lattice step from the nearest
//! triangle, with the field sign pattern of the ceiling cell around each.
//! Minutes per run, so ignored by default:
//!   BOWL_DEPTH=8 cargo test --release -p gcad-kernel --features serde \
//!       --test bowl_exact -- --ignored --nocapture
//! Env: BOWL_DEPTH (default 8), BOWL_SHIFT (nudge the cube, i.e. the lattice
//! phase), BOWL_JSON (override the fixture path).
use gcad_kernel::math::grid::make_lattice;
use gcad_kernel::scene_bridge::build_csg_tree_from_json;
use gcad_kernel::sdf::CsgNode;
use gcad_kernel::sfcc::pipeline::{PipelineTuning, SfccWorldCube};
use std::collections::HashMap;

const CUBE: SfccWorldCube = SfccWorldCube { min_x: -91.5, min_y: 75.0 - 91.5, min_z: -91.5, size: 183.0 };

fn load_tree() -> CsgNode {
    let path = std::env::var("BOWL_JSON")
        .unwrap_or_else(|_| concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/bowl-taper.json").to_string());
    let json = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!("read {path}: {e} (regenerate with `node --import tsx gcad-wasm/fixtures/dump-bowl-taper.mts --no-export`)")
    });
    build_csg_tree_from_json(&json).unwrap()
}

/// First surface point along the ray `o + t·d`, t ∈ [0, t_max], starting outside.
fn march(tree: &CsgNode, o: [f64; 3], d: [f64; 3], t_max: f64) -> Option<[f64; 3]> {
    let at = |t: f64| [o[0] + t * d[0], o[1] + t * d[1], o[2] + t * d[2]];
    let mut t = 0.0f64;
    let mut f = tree.f(at(t));
    if f <= 0.0 {
        return None;
    }
    while f > 0.0 && t < t_max {
        t += f.min(0.5).max(1e-3);
        f = tree.f(at(t));
    }
    if f > 0.0 {
        return None;
    }
    let (mut lo, mut hi) = (t - 0.5, t);
    for _ in 0..40 {
        let mid = 0.5 * (lo + hi);
        if tree.f(at(mid)) > 0.0 { lo = mid } else { hi = mid }
    }
    Some(at(0.5 * (lo + hi)))
}

/// Ray families covering every face of the bowl: outer wall (inward from r=100),
/// cavity wall (outward from the axis), cavity floor (down from y=75), underside
/// (up from y=-10), and the rim ring (down from y=160 over the wall annulus).
fn ray_families() -> Vec<(&'static str, Vec<([f64; 3], [f64; 3], f64)>)> {
    let mut out = Vec::new();
    let mut outer = Vec::new();
    let mut inner = Vec::new();
    let mut y = 2.0;
    while y < 148.0 {
        for k in 0..720 {
            let phi = k as f64 * std::f64::consts::PI / 360.0;
            let (dx, dz) = (phi.cos(), phi.sin());
            outer.push(([100.0 * dx, y, 100.0 * dz], [-dx, 0.0, -dz], 40.0));
            if y > 3.0 {
                inner.push(([0.0, y, 0.0], [dx, 0.0, dz], 95.0));
            }
        }
        y += 0.5;
    }
    out.push(("outer wall", outer));
    out.push(("cavity wall", inner));
    let mut floor = Vec::new();
    let mut under = Vec::new();
    let mut x = -84.0;
    while x < 84.0 {
        let mut z = -84.0;
        while z < 84.0 {
            floor.push(([x, 75.0, z], [0.0, -1.0, 0.0], 80.0));
            under.push(([x, -10.0, z], [0.0, 1.0, 0.0], 15.0));
            z += 0.5;
        }
        x += 0.5;
    }
    out.push(("cavity floor", floor));
    out.push(("underside", under));
    let mut rim = Vec::new();
    for k in 0..3600 {
        let phi = k as f64 * std::f64::consts::PI / 1800.0;
        let (dx, dz) = (phi.cos(), phi.sin());
        for j in 0..12 {
            let r = 89.0 + j as f64 * 0.1;
            rim.push(([r * dx, 160.0, r * dz], [0.0, -1.0, 0.0], 12.0));
        }
    }
    out.push(("rim", rim));
    out
}

#[test]
#[ignore = "minutes per run; see the module doc for the command"]
fn bowl_exact_holes() {
    let depth_max = std::env::var("BOWL_DEPTH").ok().and_then(|v| v.parse().ok()).unwrap_or(8u32);
    // BOWL_SHIFT nudges the cube (hence the lattice phase against the wall).
    let shift: f64 = std::env::var("BOWL_SHIFT").ok().and_then(|v| v.parse().ok()).unwrap_or(0.0);
    let cube = SfccWorldCube { min_x: CUBE.min_x + shift, min_y: CUBE.min_y + shift, min_z: CUBE.min_z + shift, size: CUBE.size };
    let tree = load_tree();
    // BOWL_BLEND_REFINE=0 reproduces the GUI knob `blendCurvatureRefine: false`.
    let blend_curvature_refine = std::env::var("BOWL_BLEND_REFINE").map_or(true, |v| v != "0");
    // BOWL_DECIMATE=<mm> turns on the post-pass decimation at that tolerance.
    let decimate_tol_mm: f64 = std::env::var("BOWL_DECIMATE").ok().and_then(|v| v.parse().ok()).unwrap_or(0.0);
    // BOWL_IVM=fan|centroid|project picks the cell mesher's loop triangulation.
    let interior_vertex_mode = match std::env::var("BOWL_IVM").as_deref() {
        Ok("fan") => gcad_kernel::sfcc::cell_mesh::InteriorVertexMode::Fan,
        Ok("centroid") => gcad_kernel::sfcc::cell_mesh::InteriorVertexMode::Centroid,
        _ => gcad_kernel::sfcc::cell_mesh::InteriorVertexMode::Project,
    };
    // BOWL_MULTI=1 turns on multi-sheet cells; BOWL_DEPTH_MIN overrides depth_min.
    let multi_sheet_cells = std::env::var("BOWL_MULTI").is_ok_and(|v| v == "1");
    let depth_min: u32 = std::env::var("BOWL_DEPTH_MIN").ok().and_then(|v| v.parse().ok()).unwrap_or(PipelineTuning::default().depth_min);
    let tuning = PipelineTuning { depth_min, depth_max, blend_curvature_refine, decimate_tol_mm, interior_vertex_mode, multi_sheet_cells, ..PipelineTuning::default() };
    let t0 = std::time::Instant::now();
    #[cfg(feature = "sfcc-profile")]
    gcad_kernel::sfcc::perf::reset();
    let now = || t0.elapsed().as_secs_f64() * 1e3;
    // With `--features sfcc-profile`, print the work-counter deltas at every
    // pipeline progress mark (field evaluations per phase).
    #[cfg(feature = "sfcc-profile")]
    let last = std::cell::Cell::new(([0usize; 31], 0.0f64));
    let progress = |phase: u32, label: &str, _frac: f64| {
        #[cfg(feature = "sfcc-profile")]
        {
            let c = gcad_kernel::sfcc::perf::snapshot();
            let (prev, t_prev) = last.get();
            let t = now();
            println!(
                "  [{phase}] {label:<28} +{:7.0} ms  tree_f +{:>9}  raw_grad +{:>9}  winner_evals +{:>9}  lattice_hits +{:>8}",
                t - t_prev,
                c[12] - prev[12],
                c[13] - prev[13],
                c[0] - prev[0],
                c[11] - prev[11]
            );
            last.set((c, t));
        }
        #[cfg(not(feature = "sfcc-profile"))]
        let _ = (phase, label);
    };
    let r = gcad_kernel::sfcc::pipeline::run_sfcc_pipeline_profiled_progress(&tree, &cube, &tuning, &now, &progress);
    println!(
        "exact bowl depth={depth_max}: tris={} degenerate={} multi_loop={} failed={} comps={} euler={:?} open={} off_surface={} [{}ms]",
        r.tris.len() / 3,
        r.stats.degenerate_cells,
        r.stats.multi_loop_cells,
        r.stats.failed_cells,
        r.manifold.components,
        r.manifold.euler_per_component,
        r.manifold.open_edges,
        r.validation.off_surface_vertices,
        t0.elapsed().as_millis()
    );
    println!(
        "phases ms: feature={:.0} octree={:.0} (decide={:.0} apply={:.0}) contour={:.0} cellmesh={:.0} assemble={:.0} leaves={} rounds={:?}",
        r.phase_feature_ms,
        r.phase_octree_ms,
        r.phase_octree_decide_ms,
        r.phase_octree_apply_ms,
        r.phase_contour_ms,
        r.phase_cellmesh_ms,
        r.phase_assemble_ms,
        r.stats.leaves,
        r.octree_rounds.iter().map(|(n, d, a)| (*n, d.round(), a.round())).collect::<Vec<_>>()
    );
    #[cfg(feature = "sfcc-profile")]
    {
        let c = gcad_kernel::sfcc::perf::snapshot();
        println!(
            "perf: scalar_evals={} query_misses={} raw_misses={} query_hits={} retained_lattice_hits={} scalar_compositions={} raw_compositions={} discovery_calls={} discovery_traversal_nodes={} cell_interval_computations={} discovery_interval_calls={} root_sign_walk={} strict_root_exclusions={}",
            c[0], c[1], c[2], c[3], c[11], c[12], c[13], c[18], c[19], c[20], c[30], c[27], c[28]
        );
    }

    // BOWL_SAVE=<tag> writes the mesh to .agents/tmp/bowl-d<tag>.{verts.f32,tris.u32}
    // for .agents/tmp/bowl-tri-stats.mts.
    if let Ok(tag) = std::env::var("BOWL_SAVE") {
        let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../.agents/tmp");
        let vb: Vec<u8> = r.verts.iter().flat_map(|v| v.to_le_bytes()).collect();
        let tb: Vec<u8> = r.tris.iter().flat_map(|v| v.to_le_bytes()).collect();
        std::fs::write(format!("{dir}/bowl-d{tag}.verts.f32"), vb).unwrap();
        std::fs::write(format!("{dir}/bowl-d{tag}.tris.u32"), tb).unwrap();
    }

    let vert = |i: usize| [r.verts[i * 8] as f64, r.verts[i * 8 + 1] as f64, r.verts[i * 8 + 2] as f64];
    // Normal fidelity: angle between each triangle's face normal and the field
    // gradient at its centroid. Every bowl face is a planar facet, so a triangle
    // bridging a facet crease shows up as a few degrees; report the area share
    // over 1° per band (rim top vs everything below it).
    {
        let mut area = [0.0f64; 2];
        let mut bad = [0.0f64; 2];
        let mut worst = [0.0f64; 2];
        let mut worst_tris: Vec<(f64, f64, [f64; 3])> = Vec::new();
        for tri in r.tris.chunks_exact(3) {
            let (a, b, c) = (vert(tri[0] as usize), vert(tri[1] as usize), vert(tri[2] as usize));
            let (u, v) = ([b[0] - a[0], b[1] - a[1], b[2] - a[2]], [c[0] - a[0], c[1] - a[1], c[2] - a[2]]);
            let n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
            let len = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt();
            if len <= 0.0 {
                continue;
            }
            let m = [(a[0] + b[0] + c[0]) / 3.0, (a[1] + b[1] + c[1]) / 3.0, (a[2] + b[2] + c[2]) / 3.0];
            let (_, g) = tree.grad(m);
            let gl = (g[0] * g[0] + g[1] * g[1] + g[2] * g[2]).sqrt();
            let deg = ((n[0] * g[0] + n[1] * g[1] + n[2] * g[2]) / (len * gl)).clamp(-1.0, 1.0).acos().to_degrees();
            let band = usize::from(m[1] > 148.0);
            area[band] += len / 2.0;
            worst[band] = worst[band].max(deg);
            if deg > 1.0 {
                bad[band] += len / 2.0;
                worst_tris.push((deg, len / 2.0, m));
            }
        }
        worst_tris.sort_by(|x, y| y.0.total_cmp(&x.0));
        let mut by_region: std::collections::BTreeMap<&str, f64> = Default::default();
        for (_, a, m) in &worst_tris {
            let s = 1.0 + 0.125 * (m[1] / 150.0).clamp(0.0, 1.0);
            let arc = m[0].abs() > 70.0 * s && m[2].abs() > 70.0 * s;
            let band = if m[1] > 148.0 { "rim" } else if m[1] < 16.0 { "fillet" } else if m[1] < 2.0 { "floor" } else { "wall" };
            *by_region.entry(match (band, arc) { ("rim", _) => "rim", ("fillet", true) => "fillet arc", ("fillet", false) => "fillet flat", (_, true) => "wall arc", _ => "wall flat/floor" }).or_default() += a;
        }
        println!("area>1° by region (mm²): {by_region:?}");
        let mut hist = [0.0f64; 5];
        for (deg, a, _) in &worst_tris {
            hist[[2.0, 4.0, 8.0, 16.0].iter().filter(|&&e| *deg >= e).count()] += a;
        }
        println!("area>1° by angle 1-2/2-4/4-8/8-16/16+ (mm²): {:?}", hist.map(|a| a.round()));
        let flipped: f64 = worst_tris.iter().filter(|t| t.0 > 90.0).map(|t| t.1).sum();
        println!("flipped (>90°): {} tris, {flipped:.3} mm²", worst_tris.iter().filter(|t| t.0 > 90.0).count());
        for (deg, a, m) in worst_tris.iter().take(8) {
            println!("  {deg:.1}° area {a:.4} at ({:.2},{:.2},{:.2})", m[0], m[1], m[2]);
        }
        for (band, name) in ["below rim", "rim top"].iter().enumerate() {
            println!("normals {name}: area>1° {:.2}% worst {:.1}°", 100.0 * bad[band] / area[band].max(1e-12), worst[band]);
        }
    }

    // Triangle hash by AABB (2 mm bins, so decimated triangles spanning many bins
    // are still found); nearest = point-to-triangle distance.
    let mut bins: HashMap<(i32, i32, i32), Vec<usize>> = HashMap::new();
    let key = |p: [f64; 3]| ((p[0] / 2.0).floor() as i32, (p[1] / 2.0).floor() as i32, (p[2] / 2.0).floor() as i32);
    for (t, tri) in r.tris.chunks_exact(3).enumerate() {
        let (a, b, c) = (vert(tri[0] as usize), vert(tri[1] as usize), vert(tri[2] as usize));
        let lo = key([a[0].min(b[0]).min(c[0]), a[1].min(b[1]).min(c[1]), a[2].min(b[2]).min(c[2])]);
        let hi = key([a[0].max(b[0]).max(c[0]), a[1].max(b[1]).max(c[1]), a[2].max(b[2]).max(c[2])]);
        for x in lo.0..=hi.0 {
            for y in lo.1..=hi.1 {
                for z in lo.2..=hi.2 {
                    bins.entry((x, y, z)).or_default().push(t);
                }
            }
        }
    }
    fn sub(a: [f64; 3], b: [f64; 3]) -> [f64; 3] { [a[0] - b[0], a[1] - b[1], a[2] - b[2]] }
    fn dot(a: [f64; 3], b: [f64; 3]) -> f64 { a[0] * b[0] + a[1] * b[1] + a[2] * b[2] }
    // Ericson, Real-Time Collision Detection 5.1.5.
    fn point_tri_dist(p: [f64; 3], a: [f64; 3], b: [f64; 3], c: [f64; 3]) -> f64 {
        let (ab, ac, ap) = (sub(b, a), sub(c, a), sub(p, a));
        let (d1, d2) = (dot(ab, ap), dot(ac, ap));
        let closest = if d1 <= 0.0 && d2 <= 0.0 { a } else {
            let bp = sub(p, b);
            let (d3, d4) = (dot(ab, bp), dot(ac, bp));
            if d3 >= 0.0 && d4 <= d3 { b } else {
                let vc = d1 * d4 - d3 * d2;
                if vc <= 0.0 && d1 >= 0.0 && d3 <= 0.0 {
                    let v = d1 / (d1 - d3);
                    [a[0] + v * ab[0], a[1] + v * ab[1], a[2] + v * ab[2]]
                } else {
                    let cp = sub(p, c);
                    let (d5, d6) = (dot(ab, cp), dot(ac, cp));
                    if d6 >= 0.0 && d5 <= d6 { c } else {
                        let vb = d5 * d2 - d1 * d6;
                        if vb <= 0.0 && d2 >= 0.0 && d6 <= 0.0 {
                            let w = d2 / (d2 - d6);
                            [a[0] + w * ac[0], a[1] + w * ac[1], a[2] + w * ac[2]]
                        } else {
                            let va = d3 * d6 - d5 * d4;
                            if va <= 0.0 && (d4 - d3) >= 0.0 && (d5 - d6) >= 0.0 {
                                let w = (d4 - d3) / ((d4 - d3) + (d5 - d6));
                                [b[0] + w * (c[0] - b[0]), b[1] + w * (c[1] - b[1]), b[2] + w * (c[2] - b[2])]
                            } else {
                                let denom = 1.0 / (va + vb + vc);
                                let (v, w) = (vb * denom, vc * denom);
                                [a[0] + ab[0] * v + ac[0] * w, a[1] + ab[1] * v + ac[1] * w, a[2] + ab[2] * v + ac[2] * w]
                            }
                        }
                    }
                }
            }
        };
        let d = sub(p, closest);
        dot(d, d).sqrt()
    }
    let nearest = |p: [f64; 3]| -> f64 {
        let k = key(p);
        let mut best = f64::INFINITY;
        for dx in -3..=3 {
            for dy in -3..=3 {
                for dz in -3..=3 {
                    if let Some(v) = bins.get(&(k.0 + dx, k.1 + dy, k.2 + dz)) {
                        for &t in v {
                            let tri = &r.tris[t * 3..t * 3 + 3];
                            best = best.min(point_tri_dist(p, vert(tri[0] as usize), vert(tri[1] as usize), vert(tri[2] as usize)));
                        }
                    }
                }
            }
        }
        best
    };

    // Lattice exactly as build_pipeline_context builds it (pad + jitter).
    let pad = tuning.bounds_padding_mm;
    let total = CUBE.size + 2.0 * pad;
    let step = total / ((1u64 << depth_max) as f64);
    let jx = (std::f64::consts::SQRT_2 - 1.0) * 0.25 * step;
    let jy = (3.0f64.sqrt() - 1.0) * 0.25 * step;
    let jz = (5.0f64.sqrt() - 2.0) * 0.25 * step;
    let lat = make_lattice(depth_max, cube.min_x - pad - jx, cube.min_y - pad - jy, cube.min_z - pad - jz, total);
    let cell_of = |p: [f64; 3]| -> [f64; 3] {
        [
            lat.origin_x + ((p[0] - lat.origin_x) / lat.step).floor() * lat.step,
            lat.origin_y + ((p[1] - lat.origin_y) / lat.step).floor() * lat.step,
            lat.origin_z + ((p[2] - lat.origin_z) / lat.step).floor() * lat.step,
        ]
    };

    let hole_tol = 0.6 * step;
    let mut holes: Vec<[f64; 3]> = Vec::new();
    for (name, rays) in ray_families() {
        let mut total_samples = 0usize;
        let mut family_holes = 0usize;
        let mut first: Vec<[f64; 3]> = Vec::new();
        let mut max_dist = 0.0f64;
        for (o, d, t_max) in rays {
            if let Some(p) = march(&tree, o, d, t_max) {
                total_samples += 1;
                let dist = nearest(p);
                max_dist = max_dist.max(dist);
                if dist > hole_tol {
                    family_holes += 1;
                    holes.push(p);
                    if first.len() < 4 {
                        first.push(p);
                    }
                }
            }
        }
        println!(
            "{name}: samples={total_samples} holes={family_holes} ({:.2}%) max_dist={max_dist:.2} first={:?}",
            100.0 * family_holes as f64 / total_samples.max(1) as f64,
            first.iter().map(|p| format!("({:.2},{:.2},{:.2})", p[0], p[1], p[2])).collect::<Vec<_>>()
        );
    }

    // Classify hole samples by region (flat vs corner arc) and by the sign
    // pattern of their depth-max cell: corners (8), center, face centers (6),
    // edge midpoints (12).
    let mut by_y: std::collections::BTreeMap<i64, usize> = Default::default();
    let mut corner_arc = 0usize;
    let mut with_corner_sign_change = 0usize;
    let mut center_inside = 0usize;
    let mut any27_inside = 0usize;
    let mut shown = 0usize;
    for &p in &holes {
        *by_y.entry((p[1] / 10.0).floor() as i64 * 10).or_insert(0) += 1;
        let s = 1.0 + (1.0588235294117647 - 1.0) * (p[1] / 150.0).clamp(0.0, 1.0);
        let arc = p[0].abs() > 70.0 * s && p[2].abs() > 70.0 * s;
        if arc {
            corner_arc += 1;
        }
        let c0 = cell_of(p);
        let h = lat.step;
        let mut corners = [0.0f64; 8];
        for (i, v) in corners.iter_mut().enumerate() {
            *v = tree.f([
                c0[0] + if i & 1 != 0 { h } else { 0.0 },
                c0[1] + if i & 2 != 0 { h } else { 0.0 },
                c0[2] + if i & 4 != 0 { h } else { 0.0 },
            ]);
        }
        let first = corners[0] < 0.0;
        let csc = corners.iter().any(|v| (*v < 0.0) != first);
        if csc {
            with_corner_sign_change += 1;
        }
        let center = tree.f([c0[0] + 0.5 * h, c0[1] + 0.5 * h, c0[2] + 0.5 * h]);
        if center < 0.0 {
            center_inside += 1;
        }
        let mut any_inside = center < 0.0 || corners.iter().any(|v| *v < 0.0);
        // face centers + edge midpoints
        for a in 0..3 {
            for side in 0..2 {
                let mut q = [c0[0] + 0.5 * h, c0[1] + 0.5 * h, c0[2] + 0.5 * h];
                q[a] = c0[a] + side as f64 * h;
                any_inside |= tree.f(q) < 0.0;
            }
        }
        for a in 0..3 {
            for u in 0..2 {
                for v in 0..2 {
                    let (b, c) = ((a + 1) % 3, (a + 2) % 3);
                    let mut q = [0.0; 3];
                    q[a] = c0[a] + 0.5 * h;
                    q[b] = c0[b] + u as f64 * h;
                    q[c] = c0[c] + v as f64 * h;
                    any_inside |= tree.f(q) < 0.0;
                }
            }
        }
        if any_inside {
            any27_inside += 1;
        }
        if shown < 12 {
            shown += 1;
            println!(
                "  hole at ({:.2},{:.2},{:.2}) arc={arc} corner_sign_change={csc} center={center:.3} corners=[{}]",
                p[0], p[1], p[2],
                corners.iter().map(|v| format!("{v:.2}")).collect::<Vec<_>>().join(",")
            );
        }
    }
    println!(
        "holes: corner_arc={corner_arc} flat={} | cell corner sign change={with_corner_sign_change} center inside={center_inside} any of 27 samples inside={any27_inside}",
        holes.len() - corner_arc
    );
    println!("holes by y (10mm bands): {by_y:?}");
}
